mapper.select:
SELECT d.id, d.device_code, d.device_name, d.device_model, d.warehouse_id, w.name AS warehouse_name, d.station_code, d.status, d.protocol_type, d.agent_version, d.pairing_expires_at, d.credential_expires_at, d.last_seen_at, d.last_reading_at, d.queue_depth, d.scale_connected, d.printer_connected, d.revoked_at, d.created_at, (SELECT COUNT(*) FROM xsy_scale_device_session s WHERE s.device_id = d.id AND s.ended_at IS NULL AND s.expires_at > CURRENT_TIMESTAMP) AS active_session_count FROM xsy_scale_device d LEFT JOIN xsy_warehouse w ON w.id = d.warehouse_id AND w.deleted = FALSE WHERE d.deleted = FALSE
AND d.warehouse_id IN #{scopeId}
AND FALSE AND d.warehouse_id = #{query.warehouseId} AND d.status = #{query.status}
AND (d.device_code ILIKE '%' || #{query.keyword} || '%' OR d.device_name ILIKE '%' || #{query.keyword} || '%' OR d.station_code ILIKE '%' || #{query.keyword} || '%')
ORDER BY d.created_at DESC, d.id DESC
